def stream_rows(resource, transform):
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            value = transform(row)
            yield value
    except GeneratorExit:
        # explicit close(): cleanup errors propagate
        resource.close()
        raise
    except BaseException:
        # active iteration/transform error wins over cleanup error
        try:
            resource.close()
        except BaseException:
            pass
        raise
    resource.close()
